function renderGame(){
const a=state.active,m=MISSIONS.find(x=>x.id===a?.id);if(!m){state.active=null;renderHub();return}$('#hub').hidden=true;$('#game').hidden=false;if(a.k>=m.steps.length){finishMission();return}const s=m.steps[a.k];
let inventory='';
if(s.tool==='remove')inventory='<div class="discard-zone" data-dropzone="waste-bin">'+lineIcon('remove')+'<b>Контейнер для використаних ЗІЗ</b><span>Перетягни сюди предмет з медика</span></div>';
else if(s.choices)inventory=s.choices.map((c,i)=>dragItem(s.tool,c,`data-answer="${i}"`)).join('');
else if(['green','yellow','red','black'].includes(s.tool))inventory=['green','yellow','red','black'].map(t=>dragItem(t,'Бирка: '+TOOLS[t][1])).join('');
else{let available=m.tools.filter(t=>!['green','yellow','red','black'].includes(t));const i=available.indexOf(s.tool);available=[...new Set([s.tool,...available.slice(Math.max(0,i-1),i+2),...available])].slice(0,3).sort((x,y)=>m.tools.indexOf(x)-m.tools.indexOf(y));inventory=available.map(t=>dragItem(t)).join('')}
$('#game').innerHTML=`<div class="drag-game"><div class="game-hud"><button id="pauseMission" aria-label="Зберегти й вийти">←</button><div><span>${m.name}</span><b>Дія ${a.k+1} з ${m.steps.length}</b></div><button id="openHelp" aria-label="Відкрити інструкцію та пам’ятку">?</button></div><div class="mission-progress"><i style="width:${a.k/m.steps.length*100}%"></i></div><div class="objective"><span>${a.outcome?'РЕЗУЛЬТАТ':'ЗАВДАННЯ'}</span><h2>${s.title}</h2></div>${dragScene(m,a)}<div class="inventory-dock ${s.choices?'choice-dock'+(s.choices.some(c=>c.length>35)?' long-choice':''):''}">${a.outcome?'<div class="dock-success">✓ Результат зафіксовано. Прочитай пояснення на сцені.</div>':a.prepared?'<div class="dock-instruction">'+(s.tool==='clean'?'Проведи пальцем по поверхні, щоб зняти забруднення.':'Утримуй кнопку на сцені для умовної перемотки часу.')+'</div>':'<div class="dock-label">'+(s.tool==='remove'?'Візьми предмет на медику й перетягни в контейнер':'Утримуй предмет → перетягни на об’єкт → відпусти')+'</div><div class="inventory-items">'+inventory+'</div>'}</div><div class="game-bottom"><span>Бали: ${a.scores.reduce((x,y)=>x+y,0)}</span><button id="hint">Підказка${a.hints.includes(a.k)?' відкрита':' · −1 бал'}</button><span>Без таймера</span></div><div id="actionFeedback" aria-live="polite">${a.hints.includes(a.k)&&!a.outcome?'<div class="hint">'+s.hint+'</div>':''}</div><div class="help-overlay" id="helpOverlay" hidden role="dialog" aria-modal="true" aria-label="Інструкція та пам’ятка"><div class="help-sheet"><button id="closeHelp" aria-label="Закрити пам’ятку">✕</button><h2>Як взаємодіяти</h2><p>Візьми предмет пальцем на нижній панелі. Не відпускаючи, перенеси на відповідну ділянку сцени. Коли зона підсвітиться — відпусти.</p><p>Для знімання ЗІЗ: візьми предмет на медику та перенеси в контейнер. Для сортування: перетягни кольорову бирку на постраждалого.</p><p>Мишею — ті самі рухи. Клавіатурою: обери предмет Enter, потім перейди Tab до зони й натисни Enter.</p><h3>Пам’ятка</h3><ol>${NOTES[m.id].map(t=>'<li>'+t+'</li>').join('')}</ol><p>Пам’ятка без штрафу. 2 бали — самостійно; 1 — після підказки чи виправлення; 0 — після критичної помилки.</p></div></div></div>`;
$('#pauseMission').onclick=()=>{save();renderPaused()};$('#openHelp').onclick=()=>{$('#helpOverlay').hidden=false;$('#closeHelp').focus()};$('#closeHelp').onclick=()=>{$('#helpOverlay').hidden=true;$('#openHelp').focus()};$('#helpOverlay').onkeydown=e=>{if(e.key==='Escape'){$('#helpOverlay').hidden=true;$('#openHelp').focus()}};$('#hint').onclick=()=>{if(a.outcome)return;if(!a.hints.includes(a.k))a.hints.push(a.k);save();$('#actionFeedback').innerHTML='<div class="hint">'+s.hint+'</div>'};if($('#nextStep'))$('#nextStep').onclick=()=>{a.k++;a.outcome=null;a.selected=null;a.choice=false;a.prepared=false;save();renderGame();window.scrollTo(0,0)};
wireDrag(m,a,s);if(a.prepared)wireGesture(s);
}
function wireDrag(m,a,s){
let keyboardPayload=null;const zones=[...document.querySelectorAll('[data-dropzone]')];zones.forEach(z=>{z.tabIndex=0;z.setAttribute('role','button');z.setAttribute('aria-label','Зона: '+z.textContent);z.onkeydown=e=>{if((e.key==='Enter'||e.key===' ')&&keyboardPayload){e.preventDefault();acceptDrop(keyboardPayload,z.dataset.dropzone,m,a,s);keyboardPayload=null}}});
document.querySelectorAll('[data-drag]').forEach(item=>{
const payload={tool:item.dataset.drag,answer:item.dataset.answer==null?null:+item.dataset.answer,item:item.dataset.item||null};
item.onclick=e=>{e.preventDefault()};item.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();keyboardPayload=payload;document.querySelectorAll('.inventory-item').forEach(x=>x.classList.remove('picked'));item.classList.add('picked');$('#dropMessage').textContent='Предмет обрано. Tab → потрібна зона → Enter.'}};
let drag=null;
item.onpointerdown=e=>{if(a.outcome||dragging||e.button>0)return;e.preventDefault();item.setPointerCapture(e.pointerId);const ghost=document.createElement('div');ghost.className='drag-ghost';ghost.innerHTML=item.innerHTML;ghost.style.left=e.clientX+'px';ghost.style.top=e.clientY+'px';document.body.appendChild(ghost);drag={x:e.clientX,y:e.clientY,ghost,zone:null,moved:false};item.classList.add('picked');document.querySelectorAll('.drop-zone,.discard-zone').forEach(x=>x.classList.add('drop-available'));};
item.onpointermove=e=>{if(!drag)return;drag.moved=drag.moved||Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>10;drag.ghost.style.left=e.clientX+'px';drag.ghost.style.top=e.clientY+'px';zones.forEach(z=>z.classList.remove('drop-hover'));const zone=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-dropzone]');drag.zone=zone;if(zone)zone.classList.add('drop-hover');};
const end=(e,cancel=false)=>{if(!drag)return;const d=drag;d.zone=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-dropzone]')||d.zone;drag=null;item.classList.remove('picked');zones.forEach(z=>z.classList.remove('drop-hover','drop-available'));if(cancel||!d.moved||!d.zone){d.ghost.remove();if(!cancel)$('#dropMessage').textContent='Утримуй предмет і перетягни на зону сцени.';return}const box=d.zone.getBoundingClientRect();const targetOk=d.zone.dataset.dropzone===expectedDrop(m,s);const itemOk=s.tool==='remove'?payload.item===s.unwear:s.choices?payload.answer===s.answer&&payload.tool===s.tool:payload.tool===s.tool;const valid=targetOk&&itemOk||typeof canVisualDrop==='function'&&canVisualDrop(payload,d.zone.dataset.dropzone,m,a,s);d.ghost.style.transition='left .18s,top .18s,transform .18s,opacity .18s';d.ghost.style.left=(valid?box.left+box.width/2:d.x)+'px';d.ghost.style.top=(valid?box.top+box.height/2:d.y)+'px';d.ghost.classList.add(valid?'drop-release':'drop-reject');dragging=true;setTimeout(()=>{d.ghost.remove();dragging=false;if(state.active===a&&!a.outcome)acceptDrop(payload,d.zone.dataset.dropzone,m,a,s)},200)};
item.onpointerup=e=>end(e);item.onpointercancel=e=>end(e,true);item.onlostpointercapture=e=>end(e,true);
})
}
function acceptDrop(payload,target,m,a,s){a.lastPayload={...payload,target};
if(target!==expectedDrop(m,s)){fail('Предмет потрапив не в ту зону. Перевір завдання та перетягни ще раз.',false);return}
if(s.tool==='remove'){if(payload.item!==s.unwear){fail('Зараз потрібно зняти інший предмет. Дотримуйся послідовності в пам’ятці.',s.critical);return}a.selected='remove';applyAction(s.target);return}
if(s.choices){if(payload.tool!==s.tool){fail('Цей предмет не підходить до завдання.',s.critical);return}applyChoice(payload.answer);return}
if(['green','yellow','red','black'].includes(s.tool)){if(payload.tool===s.tool)completeStep();else fail('Категорія не відповідає даним огляду. Перевір критерії START у пам’ятці.',true);return}
if(m.id==='disinfection'&&['clean','timer'].includes(s.tool)&&payload.tool===s.tool){a.prepared=true;save();renderGame();return}
a.selected=payload.tool;applyAction(s.target)
}
function gesturePanel(s){return s.tool==='clean'?`<div class="wipe-pad" id="wipePad" role="button" tabindex="0" aria-label="Очистити поверхню: проведи пальцем або натисни Enter"><span class="wipe-dirt"></span><span class="wipe-dirt"></span><span class="wipe-dirt"></span><b>Проведи пальцем ↔</b></div><div class="gesture-progress"><i id="gestureFill"></i></div><p class="gesture-note">Видали видиме забруднення до дезінфекції. Для клавіатури — Enter.</p>`:`<button class="hold-button" id="holdExposure">Утримуй · витримати експозицію</button><div class="gesture-progress"><i id="gestureFill"></i></div><p class="gesture-note">1,8 с утримання = умовна перемотка 60 хв. У реальності повністю витримують час з інструкції засобу на вологій поверхні.</p>`}
let holdFrame=null;
function wireGesture(s){
const pad=$('#wipePad'),button=$('#holdExposure');
if(pad){let last=null,total=0;const set=(v)=>{pad.style.setProperty('--clean',v);$('#gestureFill').style.width=v*100+'%';if(v>=1)completeStep()};pad.onpointerdown=e=>{pad.setPointerCapture(e.pointerId);last=[e.clientX,e.clientY]};pad.onpointermove=e=>{if(!last)return;total+=Math.hypot(e.clientX-last[0],e.clientY-last[1]);last=[e.clientX,e.clientY];set(Math.min(1,total/600))};pad.onpointerup=pad.onpointercancel=()=>{last=null};pad.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();set(1)}}}
if(button){let start=0;const cancel=()=>{if(holdFrame)cancelAnimationFrame(holdFrame);holdFrame=null;const fill=$('#gestureFill');if(fill)fill.style.width='0%'};const tick=t=>{if(!button.isConnected){cancel();return}if(!start)start=t;const v=Math.min(1,(t-start)/1800);$('#gestureFill').style.width=v*100+'%';if(v>=1){holdFrame=null;completeStep()}else holdFrame=requestAnimationFrame(tick)};const begin=()=>{if(holdFrame)return;start=0;holdFrame=requestAnimationFrame(tick)};button.onpointerdown=e=>{button.setPointerCapture(e.pointerId);begin()};button.onpointerup=button.onpointercancel=cancel;button.onkeydown=e=>{if(e.key===' '||e.key==='Enter'){e.preventDefault();begin()}};button.onkeyup=cancel;button.onblur=cancel}
}
function choicePanel(s,m){if(m.id==='disinfection'&&s.tool==='mix')return `<div class="dose-control"><label for="doseSlider">Відміряй концентрат <output id="doseValue">100 мл</output></label><input id="doseSlider" type="range" min="0" max="400" step="20" value="100"><div class="range-labels"><span>0 мл</span><span>400 мл</span></div><button class="primary" id="confirmDose">Влити відміряний об’єм</button></div>`;return `<div class="options">${s.choices.map((c,i)=>`<button data-choice="${i}"><span class="answer-letter">${'АБВ'[i]}</span>${c}</button>`).join('')}</div>`}
function renderPaused(){$('#game').hidden=true;$('#hub').hidden=false;const m=MISSIONS.find(x=>x.id===state.active.id);$('#hub').innerHTML=`<div class="panel"><h2>Місію призупинено</h2><p>${m.name} · дія ${Math.min(state.active.k+1,m.steps.length)} / ${m.steps.length}. Прогрес збережено.</p><div class="row"><button class="primary" id="resume">Продовжити</button><a class="button" href="#practice">До тренування</a><a class="button" href="#control">До підсумків</a><button id="discard">Почати іншу місію</button></div><p class="muted">Перехід до іншої місії скасує лише незавершену спробу. Завершені результати залишаться.</p></div>`;$('#resume').onclick=renderGame;$('#discard').onclick=()=>{state.active=null;save();renderHub()}}
function visualizeError(a,text){const m=MISSIONS.find(x=>x.id===a.id),s=m.steps[a.k],world=$('#simulationWorld');if(!world)return;world.querySelector('.mistake-overlay')?.remove();const p=a.lastPayload||{};let extra='',label='Потрібно виправити дію';
if(m.id==='ppe'){const sprite=$('#doctorSprite');if(sprite&&p.tool==='mask'){sprite.style.backgroundPosition='33.3333% 0';label='Медична маска не замінює респіратор при аерогенному ризику';extra='<div class="risk-cloud"></div>';sprite.insertAdjacentHTML('beforeend','<span class="wrong-medical-mask"></span>')}else if(p.target==='face'||p.target==='eyes'){if(sprite)sprite.style.backgroundPosition='100% 100%';label='Забруднення перенесено на обличчя';extra='<span class="contamination c-face"></span><span class="contamination c-hand"></span>'}else if(p.tool==='remove'){label='Порушено безпечну послідовність знімання';extra='<span class="contamination c-torso"></span><span class="contamination c-hand"></span>'}else{label='Комплект або порядок ще не відповідає ризику';extra='<div class="exposed-outline"></div>'}}
else if(m.id==='triage'){label='Бирка не відповідає даним огляду';extra=`<div class="wrong-triage ${p.tool||'red'}">${TOOLS[p.tool]?.[1]||'Категорію потрібно уточнити'}</div>`}
else if(m.id==='disinfection'){label=s.tool==='mix'?'Концентрацію розраховано неправильно':'Цикл обробки порушено';extra='<div class="unsafe-solution">!<small>Перевір розчин і послідовність</small></div>'}
else if(m.scene==='map'){label='Ризик залишився на схемі';extra='<div class="risk-path"><span>Вода / їжа</span><i>→</i><span>Люди</span></div>'}
else{label='Передача або маршрут потребує виправлення';extra='<div class="blocked-route">МАРШРУТ НЕ ПІДТВЕРДЖЕНО <b>×</b></div>'}
world.insertAdjacentHTML('beforeend',`<div class="mistake-overlay" aria-label="Візуалізація помилки">${extra}<div class="mistake-label"><b>${label}</b><span>${esc(text)}</span></div></div>`)}
function fail(text,critical){const a=state.active;visualizeError(a,text);const message=$('#dropMessage');if(message)message.textContent=(critical?'Критична помилка. ':'Спробуй ще раз. ')+text;if(!a.errors.some(x=>x.k===a.k&&x.text===text))a.errors.push({k:a.k,text,critical});a.log.push({text,error:true});save();$('#actionFeedback').innerHTML=`<div class="feedback bad"><b>${critical?'Критична помилка · 0 за цю дію':'Спробуй ще раз · максимум 1 бал'}</b><br>${esc(text)}</div>`}
function applyAction(target){const a=state.active,m=MISSIONS.find(x=>x.id===a.id),s=m.steps[a.k];if(!a.selected){$('#actionFeedback').innerHTML='<div class="hint">Спочатку обери інструмент на панелі.</div>';return}if(a.selected!==s.tool||target!==s.target){const danger=(m.id==='ppe'&&a.selected==='mask'&&target==='face')||(m.id==='ppe'&&a.selected==='remove'&&['face','straps'].includes(target)&&s.target!=='straps')||(m.id==='disinfection'&&a.selected==='disinfect'&&a.k<=5)||(m.id==='triage'&&['green','yellow','red','black'].includes(a.selected))||(m.id==='camp'&&a.selected==='place'&&s.target==='waste'&&['water','food'].includes(target));fail(danger?'Ця дія порушує безпечний алгоритм. Повернися до поточного завдання.':'Цей інструмент або об’єкт не відповідає поточному завданню. Перевір послідовність.',danger);return}if(s.choices){a.choice=true;save();renderGame();return}completeStep()}
function applyChoice(i){const a=state.active,m=MISSIONS.find(x=>x.id===a.id),s=m.steps[a.k];if(i!==s.answer){fail('Рішення не відповідає даним сценарію. Перевір умову та спробуй ще раз.',s.critical);return}completeStep()}
function completeStep(){const a=state.active,m=MISSIONS.find(x=>x.id===a.id),s=m.steps[a.k],errs=a.errors.filter(x=>x.k===a.k);a.scores[a.k]=errs.some(x=>x.critical)?0:errs.length||a.hints.includes(a.k)?1:2;a.outcome=true;a.choice=false;a.log.push({text:s.title+' — '+s.why,error:false});save();renderGame();window.scrollTo(0,0)}
function finishMission(){const a=state.active,m=MISSIONS.find(x=>x.id===a.id),got=a.scores.reduce((x,y)=>x+y,0),max=m.steps.length*2,pct=Math.round(got/max*100),old=state.results[m.id];const r={id:m.id,score:got,max,pct,grade:grade(pct),scores:a.scores,errors:a.errors,hints:a.hints,date:new Date().toISOString(),attempts:(old?.attempts||0)+1};state.results[m.id]=r;state.active=null;save();showMissionResult(m,r)}
function showMissionResult(m,r){$('#game').onclick=null;$('#game').innerHTML=`<div class="panel"><span class="eyebrow">Місію завершено</span><h1 style="font-size:32px">${m.name}</h1><div class="result-mark">${r.grade}<small style="font-size:18px;letter-spacing:0"> / 5</small></div><div class="stats"><div><strong>${r.score}/${r.max}</strong><small>балів</small></div><div><strong>${r.hints.length}</strong><small>дій з підказкою</small></div><div><strong>${r.errors.filter(x=>x.critical).length}</strong><small>критичних помилок</small></div></div><h3>Розбір виконання</h3><ol class="result-list">${m.steps.map((s,i)=>`<li><b>${r.scores[i]} / 2 · ${s.title}</b><br><small>${s.why}${r.scores[i]<2?' Потрібно повторити.':''}</small></li>`).join('')}</ol><div class="row"><button class="primary" id="backMissions">До інших місій →</button><button id="replay">Повторити</button><a class="button" href="#control">Підсумки заняття</a></div></div>`;$('#backMissions').onclick=renderHub;$('#replay').onclick=()=>showIntro(m.id);window.scrollTo(0,0)}
function totals(){const rows=MISSIONS.map(m=>state.results[m.id]),completed=rows.filter(Boolean).length;const score=rows.reduce((s,r)=>s+(r?.score||0),0),max=MISSIONS.reduce((s,m)=>s+m.steps.length*2,0),pct=Math.round(score/max*100);return {completed,score,max,pct,grade:completed===MISSIONS.length?grade(pct):null}}
function renderSummary(){const t=totals();$('#summary').innerHTML=`<div class="panel"><span class="eyebrow">Результати практичної підготовки</span><h2>${esc(state.profile.name||'Студент ще не вказаний')} ${state.profile.group?'· '+esc(state.profile.group):''}</h2><div class="stats"><div><strong>${t.completed}/6</strong><small>місій завершено</small></div><div><strong>${t.score}/${t.max}</strong><small>балів за симуляції</small></div><div><strong>${t.grade||'—'}</strong><small>${t.grade?'підсумкова оцінка за практику':'оцінка після всіх місій'}</small></div></div><table class="control-table"><thead><tr><th>СИМУЛЯЦІЯ</th><th>БАЛИ</th><th>ОЦІНКА</th><th>СПРОБИ</th></tr></thead><tbody>${MISSIONS.map(m=>{const r=state.results[m.id];return `<tr><td>${m.name}</td><td>${r?r.score+'/'+r.max:'Не пройдено'}</td><td>${r?r.grade:'—'}</td><td>${r?r.attempts:'—'}</td></tr>`}).join('')}</tbody></table><p class="muted">${t.completed<6?'Заверши всі шість місій для загальної оцінки.':'Оцінка за практику розрахована за всіма діями шести місій.'} Результат зберігається на цьому пристрої. Покажи екран викладачу або завантаж звіт.</p><div class="row"><a class="button primary" href="#missions">${t.completed<6?'Продовжити практику':'До симуляцій'}</a><button id="downloadReport" ${!t.completed?'disabled':''}>Завантажити звіт</button><button id="printReport" ${!t.completed?'disabled':''}>Друк / PDF</button></div></div>`;$('#downloadReport').onclick=downloadReport;$('#printReport').onclick=()=>window.print()}
function renderFinal(){const c=state.control,n=Object.keys(c.answers).length,correct=T.filter((q,i)=>c.answers[i]===q[2]).length;$('#finalQuiz').innerHTML=`<div class="section-title"><div><span class="eyebrow">Підсумкова перевірка знань</span><h2>Що засвоєно за заняття?</h2></div><span class="tag">${n} / ${T.length}</span></div><p class="muted">Тести охоплюють усі теми заняття. Пояснення відкриються після завершення; результат тестів не змінює оцінку за симуляції. Відповіді зберігаються при закритті сторінки.</p>${c.done?`<div class="feedback"><b>Контроль завершено: ${correct} / ${T.length} (${Math.round(correct/T.length*100)}%).</b><br>Підсумки практики наведені вище.</div>`:''}${T.map((q,i)=>`<article class="card quiz-card"><span class="eyebrow">${i+1} / ${T.length}</span><h3>${q[0]}</h3><div class="options">${q[1].map((v,j)=>`<button data-final="${i}" data-answer="${j}" aria-pressed="${c.answers[i]===j}" ${c.done?'disabled':''}>${v}</button>`).join('')}</div>${c.done?`<div class="feedback ${c.answers[i]!==q[2]?'bad':''}"><b>${c.answers[i]===q[2]?'Правильно.':'Варто повторити.'}</b> ${q[3]}</div>`:''}</article>`).join('')}${!c.done?`<button class="primary" id="finishControl" ${n<T.length?'disabled':''}>Завершити контроль · ${n}/${T.length}</button>`:''}`;$('#finalQuiz').onclick=e=>{const b=e.target.closest('[data-final]');if(b&&!c.done){c.answers[b.dataset.final]=+b.dataset.answer;save();renderFinal()}};if($('#finishControl'))$('#finishControl').onclick=()=>{if(Object.keys(c.answers).length!==T.length)return;c.done=true;c.date=new Date().toISOString();save();renderFinal();renderSummary();window.scrollTo(0,0)}}
function downloadReport(){const t=totals();let text=`ЗАНЯТТЯ №10 — РЕЗУЛЬТАТИ\nСтудент: ${state.profile.name}\nГрупа: ${state.profile.group}\nДата звіту: ${new Date().toLocaleString('uk-UA')}\nПрактика: ${t.completed}/6 місій; ${t.score}/${t.max} балів; оцінка: ${t.grade||'ще не визначена'}\n\n`;for(const m of MISSIONS){const r=state.results[m.id];text+=m.name+': '+(r?`${r.score}/${r.max}; ${r.pct}%; оцінка ${r.grade}; спроб ${r.attempts}; ${new Date(r.date).toLocaleString('uk-UA')}`:'не завершено')+'\n';if(r)m.steps.forEach((s,i)=>text+=`  ${i+1}. ${r.scores[i]}/2 — ${s.title}\n`)}text+='\nПідсумковий контроль знань: '+(state.control.done?T.filter((q,i)=>state.control.answers[i]===q[2]).length+'/'+T.length:'не завершено')+'\nПравило: 2 — самостійно, 1 — після підказки/виправлення, 0 — критична помилка.\nНавчальний локальний звіт; остаточне рішення щодо оцінки — за викладачем.';const url=URL.createObjectURL(new Blob(['\uFEFF'+text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='Заняття_10_результат.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
for(const m of MISSIONS){const r=state.results[m.id];if(r&&r.max!==m.steps.length*2){state.previousResults=state.previousResults||[];state.previousResults.push(r);delete state.results[m.id]}}
if(state.control.done&&Object.keys(state.control.answers).length!==T.length)state.control.done=false;
renderTraining();route();

